import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"常见错误","description":"","frontmatter":{"title":"常见错误","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/01-JDBC/--常见错误.md","filePath":"posts/java快速入门/第五部分：数据库/01-JDBC/--常见错误.md"}'),a={name:"posts/java快速入门/第五部分：数据库/01-JDBC/--常见错误.md"};function s(n,e,r,l,i,_){return c(),d("div",null,[...e[0]||(e[0]=[t("<div><ul><li><code>mysql java.sql.SQLException: The server time zone value</code>‘<code>XXXXXX&#39; is unrecognized or represents...</code> 解决方案：     这是由于数据库和系统时区差异所造成的。在<code>jdbc</code>连接的<code>url</code>后面加上<code>serverTimezone=GMT</code>即可解决问题，如果需要使用<code>gmt+8</code>时区，需要写成<code>GMT%2B8</code>，否则会被解析为空。再一个解决办法就是使用低版本的<code>MySQL jdbc</code>驱动，<code>5.1.28</code>不会存在时区的问题。</li></ul><p>例如： <code>url=jdbc:mysql://localhost:3306/bbs?useUnicode=true$characterEncoding=utf8</code></p><p>改为 <code>url=jdbc:mysql://localhost:3306/bbs?serverTimezone=UTC</code></p><ul><li><code>com.mysql.jdbc.exceptions.jdbc4.MySQLNonTransientConnectionException: Could not create conn</code> 解决方案： 这是因为本地的<code>mysql</code>安装的<code>8.0</code>，而项目所使用的驱动是<code>5.1</code>。可去官网下载最新驱动。</li></ul></div>",1)])])}const u=o(a,[["render",s]]);export{m as __pageData,u as default};
